#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""第75批 第1组 三部经白话精译构建脚本 (t0726 / t0731 / t0737)
只填 modern 与 intro；original_preview 从骨架读入，保证逐字一致。
"""
import json, os

ROOT = "/home/user/workspace/13511660557912876654/buddhist-ontology"
TASKS = os.path.join(ROOT, "data/baihua-tasks")
OUT = os.path.join(ROOT, "data/modern-translation")


def build(sid, intro, moderns):
    src = os.path.join(TASKS, sid + ".json")
    doc = json.load(open(src, encoding="utf-8"))
    segs = doc["translations"]
    assert len(segs) == len(moderns), (sid, len(segs), len(moderns))
    doc["intro"] = intro
    for s, m in zip(segs, moderns):
        assert m.startswith("【") and "【义解】" in m and not m.endswith("【义解】"), (sid, m[:20])
        s["modern"] = m
    dst = os.path.join(OUT, sid + ".json")
    with open(dst, "w", encoding="utf-8") as f:
        json.dump(doc, f, ensure_ascii=False, indent=1)
    print("%s 写入完成 段=%d" % (sid, len(segs)))


